// One row per product, stamped with the run date and keyed by Walmart's own
// item ID, so the sheet reads as a price history: the same item at two prices
// in two different weeks is a price change you can read straight off the sheet.
// Walmart also publishes a struck-through was price, so a cut the retailer is
// advertising is flagged the week it appears.
const weekOf = $now.toFormat('yyyy-MM-dd');

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

// Accept a number or a numeric string, so a "$49.99" never blanks the column.
const num = (v) => {
  if (typeof v === 'number' && isFinite(v)) return v;
  if (typeof v === 'string') {
    const n = parseFloat(v.replace(/[^0-9.]/g, ''));
    return isFinite(n) ? n : '';
  }
  return '';
};

// Measured over 60 rows across four different searches: outOfStock, freeShipping
// and twoDayShipping came back false on every single row, so they are not
// mapped. A column that can never change is worse than no column.
return $input.all().map((item) => {
  const p = item.json;
  const price = num(p.price);
  const wasPrice = num(p.wasPrice);
  const onSale = price !== '' && wasPrice !== '' && wasPrice > price;
  const seller = clip(p.sellerName, 80);
  return {
    json: {
      'Week of': weekOf,
      Search: p.query || '',
      Rank: p.position ?? '',
      Product: clip(p.title, 140),
      Category: p.productType || '',
      Price: price,
      'Was price': wasPrice,
      'On sale': onSale ? 'YES' : '',
      'Price cut %': onSale ? Math.round(((wasPrice - price) / wasPrice) * 100) : '',
      Seller: seller,
      'Sold by Walmart': seller === 'Walmart.com' ? 'YES' : '',
      Sponsored: p.sponsored === true ? 'YES' : '',
      Rating: typeof p.rating === 'number' ? p.rating : '',
      Reviews: typeof p.reviewCount === 'number' ? p.reviewCount : '',
      'Item ID': p.usItemId || '',
      'Product ID': p.productId || '',
      URL: p.url || '',
    },
  };
});

